import java.util.*;

public class E2MarekAndMatchingHardVersion {
    static final int MOD = 1_000_000_007;

    static class ModInt {
        static final ModInt ZERO = new ModInt(0);
        static final ModInt ONE = new ModInt(1);

        private final int v;

        private ModInt(int v) {
            this.v = (v % MOD + MOD) % MOD;
        }

        public static ModInt of(int v) {
            return new ModInt(v);
        }

        public ModInt add(ModInt other) {
            return new ModInt((this.v + other.v) % MOD);
        }

        public ModInt subtract(ModInt other) {
            return new ModInt((this.v - other.v + MOD) % MOD);
        }

        public ModInt multiply(ModInt other) {
            long prod = (long) this.v * other.v;
            return new ModInt((int) (prod % MOD));
        }

        public ModInt divide(ModInt other) {
            return this.multiply(other.inverse());
        }

        public ModInt inverse() {
            return pow(MOD - 2);
        }

        public ModInt pow(int exp) {
            long result = 1;
            long base = this.v;
            while (exp > 0) {
                if ((exp & 1) == 1) result = (result * base) % MOD;
                base = (base * base) % MOD;
                exp >>= 1;
            }
            return new ModInt((int) result);
        }

        public int getValue() {
            return v;
        }

        @Override
        public String toString() {
            return Integer.toString(v);
        }
    }

    public void solve(Scanner in, java.io.PrintWriter out) {
        int N = in.nextInt();
        int[][] P = new int[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                P[i][j] = in.nextInt();
            }
        }

        Map<BitSet, ModInt> G = new HashMap<>();
        BitSet init = new BitSet();
        init.set(0);
        G.put(init, ModInt.ONE);

        for (int i = 0; i < N; i++) {
            Map<ArrayList<Integer>, ModInt> H = new HashMap<>();
            for (Map.Entry<BitSet, ModInt> g : G.entrySet()) {
                ArrayList<Integer> S = new ArrayList<>();
                for (int m = 0; m < (1 << N); m++) {
                    if (g.getKey().get(m)) S.add(m);
                }
                H.put(S, g.getValue());
            }
            G.clear();

            for (int j = 0; j < (1 << N); j++) {
                ModInt pst = ModInt.ONE;
                for (int k = 0; k < N; k++) {
                    if ((j & (1 << k)) != 0) {
                        pst = pst.multiply(ModInt.of(P[i][k]));
                    } else {
                        pst = pst.multiply(ModInt.of(100 - P[i][k]));
                    }
                }

                for (Map.Entry<ArrayList<Integer>, ModInt> h : H.entrySet()) {
                    BitSet ans = new BitSet();
                    for (int l = 0; l < N; l++) {
                        if ((j & (1 << l)) == 0) continue;
                        for (int m : h.getKey()) {
                            if ((m & (1 << l)) == 0) {
                                ans.set(m | (1 << l));
                            }
                        }
                    }
                    if (!ans.isEmpty()) {
                        ModInt term = h.getValue().multiply(pst);
                        G.merge(ans, term, (oldVal, newVal) -> oldVal.add(newVal));
                    }
                }
            }
        }

        ModInt ans = ModInt.ZERO;
        for (ModInt val : G.values()) {
            ans = ans.add(val);
        }
        ModInt inv100 = ModInt.of(100).inverse();
        for (int i = 0; i < N * N; i++) {
            ans = ans.multiply(inv100);
        }
        out.println(ans.getValue());
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        java.io.PrintWriter out = new java.io.PrintWriter(System.out);
        new E2MarekAndMatchingHardVersion().solve(in, out);
        out.flush();
    }
}
